UPDATE companies SET description='LC Fine Foods, operating as LC Cash and Carry, has been a fixture in New Haven, Connecticut since 1965. The company was founded by Italian immigrant Italo “Leo” Ciocca, who envisioned bringing the finest Italian imports to his community. What began as a modest enterprise grew steadily through Leo’s commitment to quality and service, establishing a reputation in the wholesale food trade.

Today the business functions as both a wholesale distributor and a cash-and-carry retailer, stocking a wide range of Italian and domestic food products. Its offerings span fresh produce, deli items, groceries, pasta, oils, cheeses, bakery goods, coffee, and seasonal specialties. The remodeled New Haven store serves walk-in customers six days a week, while a delivery operation supplies restaurants, delis, and institutions across the region.

The customer base includes independent restaurants, delicatessens, institutional kitchens, and retail shoppers. The firm also works with domestic and international suppliers, emphasizing relationships with local farmers and dairy producers.

The Ciocca family’s second generation, Carlo and Danny, now lead the company after Leo’s passing in 2023.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Wholesale food distribution", "Cash-and-carry retail", "Delivery service", "Import and domestic product sourcing", "Local producer partnership program"], "industries": ["Restaurants", "Delicatessens", "Institutional food service", "Retail grocery"], "materials": ["Italian food imports", "Domestic food products", "Fresh produce", "Dairy products", "Pasta", "Olive oils", "Cheeses", "Bakery goods", "Coffee and tea", "Seasonal specialties"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Family-owned and operated since 1965", "Direct relationships with domestic and international food suppliers", "Commitment to sourcing from local farmers and dairy producers", "Combined wholesale distribution and cash-and-carry retail model", "Delivery service with technology-enabled logistics"], "facts_used": ["Founded 1965 by Italo ''Leo'' Ciocca -> /about", "Family-owned -> /about", "Headquarters New Haven, CT -> db", "Serves restaurants, delis, institutions, retail -> /about", "Offers Italian imports and domestic products -> /", "Cash-and-carry store open to public -> /", "Delivery service mentioned -> /", "Current owners Carlo and Danny -> /about", "Leo passed away 2023 -> /about", "Supports local farmers and dairy producers -> /about", "Product categories: produce, deli, groceries, pasta, oils, cheeses, bakery, coffee -> /", "Commitment to supplier relationships -> /about"], "company_type": "Distributor / reseller", "makes_products": "no", "type_evidence": "We at LC Fine Food are deeply committed to serving a diverse clientele, which includes restaurants, delis, institutions, and various other businesses that rely on us for their food supply needs.", "founded_year": "1965", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links"